KG_CODE("f:src/autoskill/rb.py","\"\"\"The real-browser surface, as daemon-side operations.\n\nWhy this module exists\n----------------------\n`rb` drives the user's **real, signed-in** browser through the extension\nbridge. It is the most dangerous surface in the tool — that browser is logged\ninto their mail, their HR system and their bank — and it was the only one that\nbypassed every guard:\n\n* no `rb.*` verb appeared in the risk table, so the permission engine never\n  saw one;\n* the CLI called the bridge directly, so nothing reached `Daemon.handle()`;\n* `audit.record` is only ever called from the daemon, so **no rb action was\n  logged at all**;\n* the URL deny list (added precisely because a banking *site* is as sensitive\n  as a banking *app*) therefore did not apply to the browser most likely to be\n  signed into a bank.\n\nMoving the operations here puts them behind the same gate as everything else.\nThe CLI contract is unchanged — `auto rb observe` still needs no `--session` —\nbecause these verbs are registered as sessionless, with the ref store held by\nthe daemon that already outlives individual CLI calls.\n\nBackground operation\n--------------------\nThe extension requests active renderer lifecycle and emulated page focus.\nTab selection and native window activation require explicit focus policy.\nScreenshots use a temporary compositor capture lease inside the extension;\nthey do not need to select the target tab to keep producing frames.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport base64\nimport io\nimport re\nimport threading\nimport time\nfrom concurrent.futures import Future, TimeoutError as FutureTimeout\nfrom contextvars import copy_context\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Any\n\nfrom .protocol import EffectState, ErrorCode, ProtocolError\nfrom .ports import BrowserMemoryPort, ResearchPort, PerceptionReporter\nfrom .contracts.models import Component, ResearchRequest, ResearchResult\nfrom .contracts.perception import PerceptionMode, PerceptionSummary\nfrom .contracts.browser_memory import (\n    ActionFeedback, BrowserFeedback, CoverageFeedback, RankingKind, RankingRequest,\n    RecordedVerb, RecoveryFeedback, ResearchFeedback, SiteStatus, TreeFeedback,\n    TreeState, VideoFeedback,\n)\n\n# The extension version that carries the verified-action verbs (snapshot,\n# domclick, focuskey, click_at, screenshot). Older bridges still drive every\n# original verb; the new ones say how to update instead of failing oddly.\nREQUIRED_EXTENSION = (0, 4, 0)\n\n# A page whose accessibility tree timed out is not asked again for this long\n# (same tab, same URL): the pixel route is used straight away. Measured in T6\n# (S137): four reads of one Oracle page, 91.5 s each, 6.5 minutes lost, while\n# OCR answered in 1.2 s.\nTREE_RETRY_AFTER_S = 300.0\n\n# How long the tree is waited for when the pixels are there to fall back on.\n# A healthy page answers in about 2 s (measured on Oracle's home page); the\n# page that never answered cost 91.5 s every time. A page the site memory\n# already knows to time out gets TREE_BUDGET_KNOWN_DEAD_S, any other page\n# TREE_BUDGET_FIRST_S; without the fallback (the flow engine) the old 90 s\n# stays, because there a tree is needed and a slow one is still worth having.\nTREE_BUDGET_FIRST_S = 15.0\nTREE_BUDGET_KNOWN_DEAD_S = 5.0\nTREE_BUDGET_FULL_S = 90.0\n\n# A tree can answer and still not hold the page. On a document record (T10,\n# S141) it named the header and 13 controls while the record itself - its\n# type, category and attachment - was only drawn, so every gate read an empty\n# page and failed. When less than this share of the words OCR reads is in the\n# tree, the drawn text is added to the observation, and the site memory keeps\n# the page as a partial tree so later reads add it without being asked.\nTREE_COVERAGE_MIN = 0.5\n\n# A step that must not fail (S145, the operator: \"this step must not fail, and\n# its success must be ensured\"). When the whole ladder is silent, these are\n# tried in turn - in the order the site memory says worked before - until one\n# makes the page answer. Each is a generic cause of a silent press:\n#   dismiss   an overlay/popup swallows the press: Escape, then the ladder\n#   patience  the site is slow: the ladder again, three times the patience\n#   text      the element is a decoy (the real control is drawn over it):\n#             press the drawn text found by OCR\n#   siblings  another element with the same role and name is the live one\n#   href      a link that ignores synthetic clicks: go to its address\n#   reload    the page is wedged: reload, wait longer, the ladder again\n#   video     record the screen while pressing once more, and analyse where\n#             it goes wrong (video.py) - also the evidence for a human\n# A step marked irreversible is never pressed again by any of them.\nRECOVERY_TACTICS = [\"dismiss\", \"patience\", \"text\", \"siblings\", \"href\",\n                    \"reload\", \"video\"]\nRECOVERY_BUDGET_S = 240.0\n\n# Around the target, how much of the page the pixel comparison looks at (CSS\n# px). The element alone misses a spinner beside it; the whole viewport\n# counts a blinking caret or a ticking clock as \"the page answered\".\nVISUAL_MARGIN = 40\n\n# How long a tab listing may be reused when resolving a deny-list target.\n# Short enough that a navigation cannot hide behind it, long enough that one\n# agent step does not pay for several listings.\nTABS_TTL_S = 1.5\n\n# Let a freshly activated tab paint before reading its accessibility tree.\nSETTLE_S = 1.5\n\n# Geometry is fetched one node at a time; this bounds a heavy page.\nMAX_BOXED_NODES = 400\n\n\ndef _ocr_line(ln: dict[str, Any]) -> str:\n    \"\"\"One OCR line as observations show it: `ocr [x,y wxh] \"text\"`, in\n    viewport CSS pixels - what `click-at`, `act --text` and `act --near`\n    take, and what profile patterns for pixel pages match.\"\"\"\n    x, y, w, h = ln[\"box\"]\n    return f'ocr [{x:.0f},{y:.0f} {w:.0f}x{h:.0f}] \"{ln[\"text\"]}\"'\n\n\ndef _call(op: str, params: dict[str, Any] | None = None,\n          timeout: float = 60.0) -> dict[str, Any]:\n    \"\"\"One bridge call, with bridge errors mapped onto protocol errors.\"\"\"\n    from . import nmhost\n    try:\n        return nmhost.rb_call(op, params, timeout=timeout)\n    except TimeoutError as exc:\n        raise ProtocolError(\n            ErrorCode.TIMEOUT, str(exc),\n            hint=\"The page may still have acted. Run `auto rb observe` \"\n                 \"before retrying.\",\n            effect_state=EffectState.UNKNOWN) from exc\n    except RuntimeError as exc:\n        msg = str(exc)\n        low = msg.lower()\n        if \" did not reply within \" in low:\n            # A timeout whose type was lost on the way (see nmhost.rb_call):\n            # still a timeout - the page may have acted, and callers key their\n            # recovery (the pixel fallback) on TIMEOUT.\n            raise ProtocolError(\n                ErrorCode.TIMEOUT, msg,\n                hint=\"The page may still have acted. Read it again with \"\n                     \"`auto rb observe` (it falls back to OCR) before retrying.\",\n                effect_state=EffectState.UNKNOWN) from exc\n        if \"no tab with id\" in low:\n            # The tab was closed or the browser reopened it under a new id\n            # (measured: after a restart the Oracle tab came back as another\n            # id). Fresh refs cannot help; a fresh tab listing does.\n            raise ProtocolError(\n                ErrorCode.TARGET_NOT_FOUND, msg,\n                hint=\"That tab no longer exists. Run `auto rb tabs` and use \"\n                     \"the current --tab-id.\") from exc\n        if \"multiple browser bridges\" in low or \"stale bridge instance\" in low:\n            # Refused before any operation reached the browser (nmhost endpoint\n            # selection or the host's instance check): nothing happened, so this\n            # must not be reported as an UNKNOWN effect (CM-46).\n            raise ProtocolError(\n                ErrorCode.AMBIGUOUS_TARGET if \"multiple\" in low else ErrorCode.DAEMON_UNAVAILABLE,\n                msg,\n                hint=\"No operation was sent. Select the intended bridge with \"\n                     \"AUTOSKILL_BROWSER and AUTOSKILL_BRIDGE_INSTANCE (the instance \"\n                     \"suffix of rb-endpoint-<browser>-<instance>.json), then retry.\",\n                effect_state=EffectState.NONE) from exc\n        if \"not connected\" in low or \"unreachable\" in low or \"no autoskill\" in low:\n            raise ProtocolError(\n                ErrorCode.DAEMON_UNAVAILABLE, msg,\n                hint=_bridge_hint()) from exc\n        if \"password\" in low:\n            raise ProtocolError(\n                ErrorCode.PERMISSION_DENIED, msg,\n                hint=\"Credentials are never typed by the agent. Ask the user \"\n                     \"with `auto request-help`.\") from exc\n        if \"unknown op\" in low:\n            raise ProtocolError(\n                ErrorCode.UNSUPPORTED,\n                f\"the browser extension is older than this tool ({msg})\",\n                hint=\"Reload the autoskill extension once (edge://extensions \"\n                     \"or chrome://extensions > autoskill bridge > reload), \"\n                     \"then `auto rb status` must report version \"\n                     + \".\".join(map(str, REQUIRED_EXTENSION)) + \" or newer.\") from exc\n        raise ProtocolError(\n            ErrorCode.INTERNAL, msg,\n            hint=\"Re-observe and use fresh refs.\",\n            effect_state=EffectState.UNKNOWN) from exc\n\n\nclass RbSurface:\n    \"\"\"Bridge operations plus the per-tab ref store, owned by the daemon.\"\"\"\n\n    def __init__(self) -> None:\n        self._refs: dict[int, dict[str, dict[str, Any]]] = {}\n        self._owned_tabs: set[int] = set()\n        self._generation: dict[int, int] = {}\n        self._last_tab: int | None = None\n        self._tabs_at: float = 0.0\n        self._tabs: list[dict[str, Any]] = []\n        # Taking the desktop foreground is opt-in. The daemon sets this\n        # from the user's policy; the default is to stay out of the way.\n        self.focus_windows = False\n        self._warned_awake = False\n        self.note: str | None = None\n        # Where screenshots go, and what the tool remembers about each site.\n        # The daemon sets both; alone (in tests) the surface keeps no memory.\n        self.home: Path = Path.home() / \".autoskill\"\n        self.memory: BrowserMemoryPort | None = None\n        self.research: ResearchPort | None = None\n        self.perception: PerceptionReporter | None = None\n        # tab id -> (monotonic time, url) of the last accessibility-tree read\n        # that timed out. See TREE_RETRY_AFTER_S.\n        self._tree_dead: dict[int, tuple[float, str | None]] = {}\n\n    # --- site memory ----------------------------------------------------------\n\n    def _remember(self, feedback: BrowserFeedback) -> None:\n        if self.memory is not None:\n            self.memory.remember(feedback)\n\n    def _sig(self, entry: dict[str, Any] | None) -> str:\n        from .contracts.grounding import signature\n        if not entry:\n            return \"\"\n        return signature(entry.get(\"role\", \"\"), entry.get(\"name\", \"\"))\n\n    # --- tabs ---------------------------------------------------------------\n\n    def tabs(self, *, fresh: bool = True) -> list[dict[str, Any]]:\n        if not fresh and (time.monotonic() - self._tabs_at) < TABS_TTL_S:\n            return self._tabs\n        self._tabs = _call(\"tabs\").get(\"tabs\", []) or []\n        self._tabs_at = time.monotonic()\n        return self._tabs\n\n    def pick_tab(self, explicit: int | None) -> int:\n        if explicit is not None:\n            return int(explicit)\n        if self._last_tab is not None:\n            return self._last_tab\n        active = [t for t in self.tabs() if t.get(\"active\")]\n        if not active:\n            raise ProtocolError(\n                ErrorCode.TARGET_NOT_FOUND,\n                \"no active tab in the user's browser\",\n                hint=\"Run `auto rb tabs` and pass --tab-id.\")\n        return int(active[0][\"tabId\"])\n\n    def url_of(self, tab_id: int | None) -> str | None:\n        \"\"\"The URL a verb would act on — what the deny list must evaluate.\n\n        Cached briefly: the permission check runs immediately before the\n        action, so a listing this fresh describes the same page.\n        \"\"\"\n        try:\n            tid = self.pick_tab(tab_id)\n        except ProtocolError:\n            return None\n        for t in self.tabs(fresh=True):\n            if int(t.get(\"tabId\", -1)) == tid:\n                return t.get(\"url\") or None\n        return None\n\n    # --- focus --------------------------------------------------------------\n\n    def _front(self, tab_id: int, *, focus: bool | None = None) -> None:\n        \"\"\"Make the tab readable and responsive, without taking the screen.\n\n        The extension requests renderer lifecycle and page-local focus\n        emulation without selecting the tab. Captures manage their own\n        compositor lifetime; renderer readiness alone is not proof that\n        a hidden surface will produce successive screenshots.\n\n        The desktop foreground is taken only when `focus` is asked for,\n        because burying the window someone is working in is a real cost\n        and was never the point.\n        \"\"\"\n        from . import nmhost\n        self._owned_tabs.add(tab_id)\n        want = self.focus_windows if focus is None else focus\n        res = _call(\"activate\", {\"tabId\": tab_id, \"focus\": bool(want)})\n        if want:\n            try:\n                nmhost.raise_chrome_for(tab_id)\n            except Exception:\n                pass      # OS raise is best effort; the tab is active\n        elif not res.get(\"kept_awake\", False):\n            # The renderer could not be pinned awake, so an occluded\n            # window may still swallow input. Say so once rather than\n            # let a click quietly do nothing.\n            if not self._warned_awake:\n                self._warned_awake = True\n                self.note = (\"this browser would not hold the page awake \"\n                             \"without focus; if clicks stop taking \"\n                             \"effect, run with focus enabled\")\n        self._last_tab = tab_id\n\n    # --- refs ---------------------------------------------------------------\n\n    def _resolve(self, tab_id: int, ref: str) -> dict[str, Any]:\n        key = ref if ref.startswith(\"@\") else \"@\" + ref\n        entry = (self._refs.get(tab_id) or {}).get(key)\n        if entry is None:\n            known = len(self._refs.get(tab_id) or {})\n            raise ProtocolError(\n                ErrorCode.UNKNOWN_REF,\n                f\"{key} is not in the last observation of tab {tab_id} \"\n                f\"({known} refs)\",\n                hint=\"Run `auto rb observe` and use a ref from that output.\")\n        return entry\n\n    def _refuse_if_sensitive(self, entry: dict[str, Any], ref: str) -> None:\n        if entry.get(\"sensitive\"):\n            raise ProtocolError(\n                ErrorCode.PERMISSION_DENIED,\n                f\"{ref} is a password field\",\n                hint=\"The agent never types credentials. Ask the user to \"\n                     \"enter it with `auto request-help`.\")\n\n    def reset(self) -> dict[str, Any]:\n        \"\"\"Forget every ref and cached tab. Nothing in the browser moves.\n\n        Called when a session ends, and available on its own, because\n        this surface has no session of its own to expire with.\n        \"\"\"\n        tabs = len(self._refs)\n        refs = sum(len(v) for v in self._refs.values())\n        self._refs.clear()\n        self._generation.clear()\n        self._last_tab = None\n        self._tabs = []\n        self._tabs_at = 0.0\n        return {\"effect_state\": EffectState.NONE.value, \"cleared\": True,\n                \"refs_dropped\": refs, \"tabs_forgotten\": tabs,\n                \"note\": \"Nothing in the browser changed; only what this \"\n                        \"tool remembered about it.\"}\n\n    # --- verbs --------------------------------------------------------------\n\n    def stop(self, *, exclude_tabs=()) -> dict[str, Any]:\n        \"\"\"Remove only this session's visual layer and debugger attachments.\"\"\"\n        errors = []\n        for tid in self._owned_tabs - set(exclude_tabs):\n            try:\n                _call(\"stop\", {\"tabId\": tid}, timeout=10)\n            except ProtocolError as exc:\n                errors.append({\"tab_id\": tid, \"error\": exc.error.message})\n        self._owned_tabs.clear()\n        result = self.reset()\n        result[\"cleanup_errors\"] = errors\n        return result\n\n    def status(self) -> dict[str, Any]:\n        out = _call(\"ping\", timeout=15)\n        version = str(out.get(\"version\") or \"0.1.0\")\n        res = {\"effect_state\": EffectState.NONE.value, \"connected\": True,\n               \"extension\": out.get(\"ext\"), \"version\": version,\n               \"tabs_known\": len(self._tabs)}\n        try:\n            have = tuple(int(x) for x in version.split(\".\")[:3])\n        except ValueError:\n            have = (0, 0, 0)\n        if have < REQUIRED_EXTENSION:\n            res[\"note\"] = (\"the loaded extension is \" + version + \"; reload it \"\n                           \"once in edge://extensions (or chrome://extensions) \"\n                           \"to enable the newest verbs (act, ocr, click-at, \"\n                           \"screenshot, locate); after that `auto rb \"\n                           \"selfreload` does it\")\n        return res\n\n    def list_tabs(self) -> dict[str, Any]:\n        tabs = self.tabs()\n        return {\"effect_state\": EffectState.NONE.value, \"tabs\": tabs,\n                \"count\": len(tabs)}\n\n    def open(self, url: str) -> dict[str, Any]:\n        out = _call(\"open\", {\"url\": url, \"focus\": self.focus_windows})\n        tid = int(out[\"tabId\"])\n        self._last_tab = tid\n        self._tabs_at = 0.0\n        self._remember(ActionFeedback(None, RecordedVerb.OPEN, to_url=url))\n        return {\"effect_state\": EffectState.COMMITTED.value, \"tab_id\": tid,\n                \"url\": url}\n\n    def activate(self, tab_id: int | None) -> dict[str, Any]:\n        tid = self.pick_tab(tab_id)\n        self._front(tid)\n        return {\"effect_state\": EffectState.COMMITTED.value, \"tab_id\": tid}\n\n    def navigate(self, url: str, tab_id: int | None) -> dict[str, Any]:\n        tid = self.pick_tab(tab_id)\n        self._front(tid)\n        before = self.url_of(tid)\n        _call(\"navigate\", {\"tabId\": tid, \"url\": url})\n        self._refs.pop(tid, None)          # a new document voids every ref\n        self._tabs_at = 0.0\n        self._remember(ActionFeedback(before, RecordedVerb.NAVIGATE, to_url=url))\n        return {\"effect_state\": EffectState.COMMITTED.value, \"tab_id\": tid,\n                \"url\": url}\n\n    def observe(self, tab_id: int | None, *,\n                max_tokens: int | None = None,\n                fallback: bool = False,\n                ocr: bool = False) -> dict[str, Any]:\n        \"\"\"The page's accessibility tree as @eN refs.\n\n        With `fallback`, a tree that cannot be read (the bridge's `ax` call\n        timed out) is not asked again: the page is read by its pixels instead\n        (`_pixel_observation`) and the tab is remembered, so the next read of\n        the same page goes straight to the pixels for TREE_RETRY_AFTER_S. The\n        flow engine does not pass `fallback`: its patterns need refs, and a\n        failure there must stay a failure it can heal.\n\n        With `ocr` - and, under `fallback`, on any page the site memory knows\n        to have a partial tree - a tree that answers is checked against what\n        is drawn: below TREE_COVERAGE_MIN the OCR lines are added after an\n        `@partial-tree` line (`_with_drawn_text`).\n        \"\"\"\n        from .browser.perceive import INTERACTIVE_ROLES\n        from . import nmhost\n        tid = self.pick_tab(tab_id)\n        self._front(tid)\n        url = self.url_of(tid)\n        dead = self._tree_dead.get(tid)\n        if fallback and dead and dead[1] == url and \\\n                time.monotonic() - dead[0] < TREE_RETRY_AFTER_S:\n            return self._pixel_observation(\n                tid, f\"the accessibility tree of this page timed out \"\n                     f\"{time.monotonic() - dead[0]:.0f}s ago; not waiting \"\n                     f\"for it again\")\n        time.sleep(SETTLE_S)\n        budget = self._tree_budget(url) if fallback else TREE_BUDGET_FULL_S\n        try:\n            ax = _call(\"ax\", {\"tabId\": tid}, timeout=budget)\n        except ProtocolError as exc:\n            if not fallback or exc.error.code != ErrorCode.TIMEOUT:\n                raise\n            self._tree_dead[tid] = (time.monotonic(), url)\n            self._remember(TreeFeedback(url, False, exc.error.message))\n            return self._pixel_observation(tid, exc.error.message)\n        if self._tree_dead.pop(tid, None) is not None:\n            self._remember(TreeFeedback(url, True))\n        ids = [n[\"backendDOMNodeId\"] for n in ax.get(\"nodes\", [])\n               if (n.get(\"role\") or \"\").lower() in INTERACTIVE_ROLES\n               and (n.get(\"name\") or n.get(\"value\"))\n               and n.get(\"backendDOMNodeId\")]\n        boxes = _call(\"boxes\", {\"tabId\": tid,\n                                \"backendIds\": ids[:MAX_BOXED_NODES]},\n                      timeout=90)\n        obs = nmhost.render_observation(ax, boxes)\n        self._refs[tid] = obs[\"refs\"]\n        self._generation[tid] = self._generation.get(tid, 0) + 1\n        text = obs[\"text\"]\n        out = {\"effect_state\": EffectState.NONE.value, \"tab_id\": tid,\n               \"ref_count\": len(obs[\"refs\"]), \"node_count\": obs[\"node_count\"],\n               \"generation\": self._generation[tid]}\n        # The tree answered; does it hold what is drawn? (T10)\n        if ocr or (fallback and self._tree_partial(url)):\n            text = self._with_drawn_text(tid, url, text, out)\n        # Only the refs that point somewhere, so a caller can identify a\n        # row without opening it. Audit keeps none of this: the summary\n        # whitelist does not include it.\n        links = {r: e[\"href\"] for r, e in obs[\"refs\"].items() if e.get(\"href\")}\n        if links:\n            out[\"hrefs\"] = links\n        # Same token budget as the dedicated-browser surface. The recorded\n        # BrowserSkill session passed one on *every* observe; an observation\n        # that silently eats the context window is a cost bug.\n        if max_tokens:\n            limit = int(max_tokens * 3.6)\n            if len(text) > limit:\n                kept: list[str] = []\n                lines, used = text.splitlines(), 0\n                cut = len(lines)\n                for i, line in enumerate(lines):\n                    if used + len(line) + 1 > limit and kept:\n                        cut = i\n                        break\n                    kept.append(line)\n                    used += len(line) + 1\n                text = (\"\\n\".join(kept)\n                        + f\"\\n\\n@truncated {len(lines) - cut} lines cut by \"\n                          f\"--max-tokens; narrow the page or raise the budget\")\n                out[\"truncated_lines\"] = len(lines) - cut\n            out[\"est_tokens\"] = int(len(text) / 3.6)\n        out[\"text\"] = text\n        # Is this an interface we know, a changed one, or a new one? Checked\n        # on the FULL observation, before any budget cut, so a truncated read\n        # never looks like a site that lost half its controls.\n        if self.memory is not None:\n            site = self.memory.assess(self.url_of(tid), obs[\"text\"])\n            # Retain the public CLI shape; the internal port carries a contract.\n            result = {\"host\": site.host, \"page\": site.page, \"elements\": site.elements,\n                      \"similarity\": site.similarity, \"status\": site.status.value}\n            for key in (\"state\", \"label\", \"origin\", \"confidence\", \"stale\"):\n                value = getattr(site, key)\n                if value is not None:\n                    result[key] = value\n            if site.status is SiteStatus.CHANGED:\n                result.update(removed=list(site.removed), added=list(site.added),\n                              breaking=list(site.breaking))\n            out[\"site\"] = result\n        if self.perception is not None:\n            self.perception.report(PerceptionSummary(\n                Component.BROWSER, PerceptionMode.ACCESSIBILITY, len(obs['refs']),\n                obs['node_count'], bool(out.get('truncated_lines')), None))\n        return out\n\n    def click(self, ref: str, tab_id: int | None) -> dict[str, Any]:\n        tid = self.pick_tab(tab_id)\n        entry = self._resolve(tid, ref)\n        self._front(tid)\n        out = _call(\"click\", {\"tabId\": tid, \"backendNodeId\": entry[\"backend\"]})\n        self._remember(ActionFeedback(self.url_of(tid), RecordedVerb.CLICK,\n                                      target=self._sig(entry), method=\"cdp\"))\n        return {\"effect_state\": EffectState.COMMITTED.value, \"tab_id\": tid,\n                \"target\": f'{ref} {entry[\"role\"]} {entry[\"name\"]!r}',\n                \"at\": [round(out.get(\"x\", 0)), round(out.get(\"y\", 0))]}\n\n    def type_text(self, text: str, ref: str | None,\n                  tab_id: int | None) -> dict[str, Any]:\n        tid = self.pick_tab(tab_id)\n        entry = None\n        if ref:\n            entry = self._resolve(tid, ref)\n            self._refuse_if_sensitive(entry, ref)\n        self._front(tid)\n        if entry is not None:\n            _call(\"click\", {\"tabId\": tid, \"backendNodeId\": entry[\"backend\"]})\n        out = _call(\"type\", {\"tabId\": tid, \"text\": text})\n        self._remember(ActionFeedback(self.url_of(tid), RecordedVerb.TYPE,\n                                      target=self._sig(entry), text=text))\n        return {\"effect_state\": EffectState.COMMITTED.value, \"tab_id\": tid,\n                \"chars\": out.get(\"chars\", len(text)), \"target\": ref}\n\n    def press(self, key: str, tab_id: int | None) -> dict[str, Any]:\n        tid = self.pick_tab(tab_id)\n        self._front(tid)\n        _call(\"key\", {\"tabId\": tid, \"key\": key})\n        self._remember(ActionFeedback(self.url_of(tid), RecordedVerb.KEY, text=key))\n        return {\"effect_state\": EffectState.COMMITTED.value, \"tab_id\": tid,\n                \"key\": key}\n\n    def upload(self, ref: str, files: list[str],\n               tab_id: int | None) -> dict[str, Any]:\n        tid = self.pick_tab(tab_id)\n        entry = self._resolve(tid, ref)\n        self._front(tid)\n        out = _call(\"upload\", {\"tabId\": tid, \"backendNodeId\": entry[\"backend\"],\n                               \"files\": files})\n        return {\"effect_state\": EffectState.COMMITTED.value, \"tab_id\": tid,\n                \"target\": ref, \"files\": out.get(\"set\", len(files))}\n\n    def reload(self, tab_id: int | None) -> dict[str, Any]:\n        tid = self.pick_tab(tab_id)\n        self._front(tid)\n        _call(\"reload\", {\"tabId\": tid})\n        self._refs.pop(tid, None)\n        self._remember(ActionFeedback(self.url_of(tid), RecordedVerb.RELOAD))\n        return {\"effect_state\": EffectState.COMMITTED.value, \"tab_id\": tid}\n\n    def cue(self, tab_id: int | None, **fields: Any) -> dict[str, Any]:\n        \"\"\"A bare overlay cue - the waiting dots, a narration line. Cosmetic\n        by definition: it moves no input, reads nothing, and a bridge that\n        cannot show it changes nothing about the work (S157).\"\"\"\n        try:\n            tid = self.pick_tab(tab_id)\n            _call(\"cue\", {\"tabId\": tid, **fields})\n        except Exception:\n            pass           # a decoration never blocks the work it decorates\n        return {\"effect_state\": EffectState.NONE.value}\n\n    def wait(self, name: str, role: str | None, timeout: float,\n             tab_id: int | None) -> dict[str, Any]:\n        tid = self.pick_tab(tab_id)\n        # Every other operation fronts the tab first; this one did not, and\n        # it is the one that polls for the longest. `getFullAXTree` on a tab\n        # that is not active in its window returns a bare root, so a 45s wait\n        # searched an empty tree and timed out while the button was on the\n        # page the whole time. Measured on a request that opened in a\n        # background popup window.\n        self._front(tid)\n        # The waiting dots: a wait is exactly the \"loading / waiting for an\n        # update\" moment the user should SEE as one (S157).\n        self.cue(tid, wait=True)\n        try:\n            out = _call(\"wait\", {\"tabId\": tid, \"name\": name, \"role\": role,\n                                 \"timeout\": timeout},\n                        timeout=timeout + 20)\n        finally:\n            self.cue(tid, wait=False)\n        if not out.get(\"found\"):\n            raise ProtocolError(\n                ErrorCode.TIMEOUT,\n                f\"no element matching {name!r} appeared within {timeout:g}s\",\n                hint=\"Run `auto rb observe` to see what the page contains.\")\n        self._remember(ActionFeedback(self.url_of(tid), RecordedVerb.WAIT,\n                                      target=f\"{(out.get('role') or '').lower()}|{name}\"))\n        return {\"effect_state\": EffectState.NONE.value, \"tab_id\": tid,\n                \"found\": True, \"role\": out.get(\"role\"), \"name\": out.get(\"name\")}\n\n    def close(self, tab_id: int | None) -> dict[str, Any]:\n        tid = self.pick_tab(tab_id)\n        _call(\"close\", {\"tabId\": tid})\n        self._refs.pop(tid, None)\n        self._tabs_at = 0.0\n        if self._last_tab == tid:\n            self._last_tab = None\n        return {\"effect_state\": EffectState.COMMITTED.value, \"closed\": tid}\n\n    def _tree_partial(self, url: str | None) -> bool:\n        \"\"\"Has this page's tree been seen to miss most of what is drawn?\n        Once seen, always checked: a record drawn outside its tree stays so.\"\"\"\n        st = self.memory.tree(url) if self.memory is not None else TreeState()\n        return bool(st.last_partial)\n\n    def note_tree_coverage(self, url: str | None,\n                           coverage: float | None) -> None:\n        \"\"\"Keep, per page, how much of the drawn text the tree carries.\"\"\"\n        if coverage is None:\n            return\n        self._remember(CoverageFeedback(url, float(coverage),\n                                        float(coverage) < TREE_COVERAGE_MIN))\n\n    def _with_drawn_text(self, tid: int, url: str | None, text: str,\n                         out: dict[str, Any]) -> str:\n        \"\"\"The tree's text, plus what OCR reads when the tree misses most of\n        it. OCR failing leaves the tree's text as it was.\"\"\"\n        from .analyse import ocr_coverage\n        try:\n            seen = self.ocr(tid)\n        except ProtocolError as exc:\n            out[\"ocr_error\"] = exc.error.message\n            return text\n        lines = seen.get(\"lines\") or []\n        cov = ocr_coverage(text, \"\\n\".join(ln[\"text\"] for ln in lines))\n        out[\"ocr_coverage\"] = cov.get(\"coverage\")\n        self.note_tree_coverage(url, cov.get(\"coverage\"))\n        if cov.get(\"coverage\") is None or cov[\"coverage\"] >= TREE_COVERAGE_MIN:\n            return text\n        out[\"mode\"] = \"tree+ocr\"\n        # The tree's own text, kept apart: anything that measures the tree\n        # (analyse) must not measure the OCR lines added to it.\n        out[\"tree_text\"] = text\n        drawn = [f\"@partial-tree only {cov['coverage']:.0%} of the words drawn \"\n                 f\"on screen are in the tree; the drawn text follows (no refs: \"\n                 f\"use `rb act --near TEXT` or `rb act --text`)\"]\n        drawn += [_ocr_line(ln) for ln in lines]\n        return text + \"\\n\" + \"\\n\".join(drawn)\n\n    def _tree_budget(self, url: str | None) -> float:\n        \"\"\"Seconds to wait for the tree when the pixels can take over.\"\"\"\n        st = self.memory.tree(url) if self.memory is not None else TreeState()\n        if st.timeouts and st.last_timeout > st.last_ok:\n            return TREE_BUDGET_KNOWN_DEAD_S\n        return TREE_BUDGET_FIRST_S\n\n    # --- seeing by pixels -----------------------------------------------------\n\n    def _pixel_observation(self, tid: int, reason: str) -> dict[str, Any]:\n        \"\"\"An observation made of what is DRAWN, for a page whose tree cannot\n        be read. No refs (none would be valid); every line is OCR text with\n        its box in viewport CSS pixels - what `click-at`, `act --text` and\n        `act --near` work from.\"\"\"\n        self._refs.pop(tid, None)\n        seen = self.ocr(tid)\n        lines = [f\"@unreadable-tree {reason}\",\n                 \"@mode ocr - no refs; use `rb act --text`, `rb act --near \"\n                 \"TEXT --pick ...`, `rb locate --near TEXT` or `rb click-at`\"]\n        lines += [_ocr_line(ln) for ln in seen.get(\"lines\") or []]\n        text = \"\\n\".join(lines)\n        out = {\"effect_state\": EffectState.NONE.value, \"tab_id\": tid,\n               \"mode\": \"ocr\", \"ref_count\": 0, \"node_count\": 0,\n               \"tree_error\": reason, \"lines\": seen.get(\"lines\") or [],\n               \"image\": seen.get(\"image\"), \"text\": text}\n        if self.perception is not None:\n            self.perception.report(PerceptionSummary(\n                Component.BROWSER, PerceptionMode.OCR_FALLBACK, 0, 0, False, None))\n        return out\n\n    def _shot(self, tid: int, *, keep_overlay: bool = False) -> tuple[Any, dict[str, Any]]:\n        \"\"\"The viewport as a PIL image, plus how to map it to CSS pixels.\n        keep_overlay leaves the agent's own cursor and status bar in the\n        pixels - the self-monitoring path films the agent at work.\"\"\"\n        from PIL import Image\n        out = _call(\"screenshot\", {\"tabId\": tid, \"keepOverlay\": keep_overlay},\n                    timeout=60)\n        img = Image.open(io.BytesIO(base64.b64decode(out[\"data\"])))\n        img.load()\n        meta = {k: out.get(k) for k in (\"dpr\", \"vw\", \"vh\", \"sx\", \"sy\")}\n        vw = meta.get(\"vw\") or img.size[0]\n        meta[\"dpr\"] = float(meta.get(\"dpr\") or (img.size[0] / max(1, vw)))\n        return img, meta\n\n    def screenshot(self, tab_id: int | None,\n                   out: str | None = None,\n                   with_overlay: bool = False) -> dict[str, Any]:\n        tid = self.pick_tab(tab_id)\n        self._front(tid)\n        img, meta = self._shot(tid, keep_overlay=with_overlay)\n        path = Path(out).expanduser() if out else (\n            self.home / \"shots\" /\n            f\"rb-{tid}-{datetime.now().strftime('%Y%m%d-%H%M%S-%f')}.png\")\n        path.parent.mkdir(parents=True, exist_ok=True)\n        img.save(path)\n        return {\"effect_state\": EffectState.NONE.value, \"tab_id\": tid,\n                \"path\": str(path), \"width\": img.size[0], \"height\": img.size[1],\n                **meta}\n\n    def ocr(self, tab_id: int | None, *, lang: str | None = None,\n            find: str | None = None, nth: int = 1) -> dict[str, Any]:\n        \"\"\"Read the viewport's text by OCR, in CSS pixels of the viewport -\n        the coordinates `click-at` takes.\"\"\"\n        from . import ocr as _ocr\n        shot = self.screenshot(tab_id)\n        res = _ocr.recognize(shot[\"path\"], lang=lang)\n        k = 1.0 / (shot.get(\"dpr\") or 1.0)\n        lines = [{\"text\": ln[\"text\"], \"box\": [round(v * k, 1) for v in ln[\"box\"]]}\n                 for ln in res[\"lines\"]]\n        out = {\"effect_state\": EffectState.NONE.value, \"tab_id\": shot[\"tab_id\"],\n               \"lang\": res.get(\"lang\"), \"available\": res.get(\"available\"),\n               \"image\": shot[\"path\"], \"dpr\": shot.get(\"dpr\"),\n               \"lines\": lines, \"count\": len(lines)}\n        if find:\n            hits = _ocr.find(res, find, nth=nth)\n            out[\"matches\"] = [{**h, \"box\": [round(v * k, 1) for v in h[\"box\"]],\n                               \"at\": [round(c * k, 1) for c in _ocr.centre(h[\"box\"])]}\n                              for h in hits]\n        return out\n\n    def click_at(self, x: float, y: float, tab_id: int | None, *,\n                 dry: bool = False) -> dict[str, Any]:\n        \"\"\"A real input event at viewport CSS coordinates.\"\"\"\n        from .contracts.grounding import signature\n        tid = self.pick_tab(tab_id)\n        self._front(tid)\n        out = _call(\"click_at\", {\"tabId\": tid, \"x\": float(x), \"y\": float(y),\n                                 \"dry\": bool(dry)})\n        hit = out.get(\"hit\") or {}\n        if not dry:\n            self._remember(ActionFeedback(self.url_of(tid), RecordedVerb.CLICK_AT,\n                           target=signature(hit.get(\"tag\", \"\"),\n                                            hit.get(\"text\", \"\")),\n                           method=\"position\"))\n        return {\"effect_state\": (EffectState.NONE.value if dry\n                                 else EffectState.COMMITTED.value),\n                \"tab_id\": tid, \"at\": [x, y], \"hit\": hit}\n\n    def locate(self, near: str, tab_id: int | None, *, nth: int = 1,\n               pick: str | None = None) -> dict[str, Any]:\n        \"\"\"The controls in the same row as a text drawn on the page - the way\n        to reach an icon that has no accessible name (T6: the view and\n        download icons of an Oracle document record). The text is found by\n        OCR, its row by the page itself (`row_controls`), and each control\n        comes back with its title/alt/id and its DOM node.\"\"\"\n        from . import ocr as _ocr\n        tid = self.pick_tab(tab_id)\n        seen = self.ocr(tid, find=near, nth=nth)\n        hits = [h for h in seen.get(\"matches\") or [] if h[\"score\"] >= 0.85]\n        if not hits:\n            raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                                f\"OCR does not see {near!r} on the page\",\n                                hint=\"Check the text with `auto rb ocr`; the \"\n                                     \"row must be visible (scroll first).\")\n        x, y = hits[0][\"at\"]\n        row = _call(\"row_controls\", {\"tabId\": tid, \"x\": x, \"y\": y})\n        controls = row.get(\"controls\") or []\n        for i, c in enumerate(controls, 1):\n            c[\"index\"] = i\n            c[\"label\"] = control_label(c)\n        out = {\"effect_state\": EffectState.NONE.value, \"tab_id\": tid,\n               \"near\": near, \"anchor\": [x, y], \"row\": row.get(\"row\"),\n               \"controls\": controls, \"count\": len(controls),\n               \"trail\": row.get(\"trail\") or []}\n        if row.get(\"reason\"):\n            out[\"note\"] = row[\"reason\"]\n        if pick:\n            out[\"picked\"] = pick_control(controls, pick, [x, y])\n        return out\n\n    # --- verified action ------------------------------------------------------\n\n    def act(self, *, ref: str | None = None, text: str | None = None,\n            tab_id: int | None = None, methods: list[str] | None = None,\n            patience: float | None = None, irreversible: bool = False,\n            reload_ok: bool = True, expect_appear: list[str] | None = None,\n            expect_gone: list[str] | None = None, visual: bool = True,\n            nth: int = 1, near: str | None = None,\n            pick: str | None = None,\n            expect_new_tab: bool = False,\n            expect_download: str | None = None,\n            ensure: bool = True, accept_weak: bool = False) -> dict[str, Any]:\n        \"\"\"Press something and PROVE the page answered, trying method after\n        method (see act.py). `ref` names an element from the last observe;\n        `text` finds it by what is drawn, for pages whose tree is unreadable.\n\n        With `ensure` (the default), a ladder that ends silent is not the end:\n        the recovery tactics run (`_recover`), the public knowledge bases are\n        searched in the background, and the screen is recorded and analysed.\n        An irreversible press is never repeated; it gets the search and a\n        recording of what the page does next.\n\n        `accept_weak` is for a caller with its own proof of the press (the\n        flow engine: the next step's wait, the commit's `proves`). A look-only\n        answer is accepted there, as it was in the live approvals T9 and T11\n        (Claim answered with its style after ~5 s, Approve appeared later);\n        only a press with no answer at all goes on to the recovery. Without\n        it, the ladder went on pressing Claim, reloaded the task page and\n        could press Escape over a dialog Oracle had opened (S146 audit).\n        \"\"\"\n        from .act import DEFAULT_PATIENCE_S, Actor, not_verified_error\n        from .contracts.grounding import signature\n        if not ref and not text and not near:\n            raise ProtocolError(ErrorCode.UNSUPPORTED,\n                                \"act needs a ref, a text, or --near with --pick\",\n                                hint='auto rb act @e5   |   auto rb act --text '\n                                     '\"Approve\"   |   auto rb act --near \"Photo\" '\n                                     '--pick right')\n        tid = self.pick_tab(tab_id)\n        target: dict[str, Any] = {\"nth\": nth}\n        if near:\n            found = self.locate(near, tid, nth=nth, pick=pick or \"right\")\n            c = found.get(\"picked\")\n            if not c:\n                raise ProtocolError(\n                    ErrorCode.TARGET_NOT_FOUND,\n                    f\"no control matching {pick or 'right'!r} in the row of \"\n                    f\"{near!r}\",\n                    hint=\"Controls in that row: \" + \"; \".join(\n                        f\"{x['index']}:{x['label']}\" for x in found[\"controls\"])\n                    + \" - pick one by number, left/right, or name:WORD.\")\n            target.update(backend=c.get(\"backendNodeId\"), role=c.get(\"tag\", \"\"),\n                          name=c[\"label\"], at=[c[\"cx\"], c[\"cy\"]],\n                          sig=signature(\"icon\", f\"{near} {c['label']}\"))\n            # an icon has no text for the OCR method; its position is known\n            methods = methods or [\"cdp\", \"dom\", \"keyboard\", \"position\"]\n        elif ref:\n            entry = self._resolve(tid, ref)\n            self._refuse_if_sensitive(entry, ref)\n            target.update(ref=ref, backend=entry[\"backend\"],\n                          role=entry.get(\"role\", \"\"), name=entry.get(\"name\", \"\"),\n                          text=text or entry.get(\"name\", \"\"),\n                          sig=self._sig(entry))\n        else:\n            target.update(text=text, role=\"text\", name=text,\n                          sig=signature(\"text\", text or \"\"))\n        expect: dict[str, bool] = {}\n        for n in expect_appear or []:\n            expect[n] = True\n        for n in expect_gone or []:\n            expect[n] = False\n        if expect_new_tab:\n            expect[\"@new-tab\"] = True\n        download_dir = None\n        if expect_download:\n            download_dir = Path(expect_download).expanduser()\n            if not download_dir.is_dir():\n                raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                                    f\"no downloads folder at {download_dir}\",\n                                    hint=\"Pass the folder the browser saves to.\")\n            expect[\"@download\"] = True\n        self._front(tid)\n        # Where the action is PERFORMED - the recipe's page. Taken before the\n        # press: after it, the URL is already the next page's (T8 recipe).\n        page_url = self.url_of(tid)\n        learned: list[str] = []\n        if ensure and not irreversible:\n            methods, patience, learned = self._prepare_from_memory(\n                tid, page_url, target, methods, patience)\n        actor = Actor(_RbPort(self, tid, expect, download_dir=download_dir),\n                      memory=self.memory)\n        res = actor.act(target, methods=methods,\n                        patience_s=patience or DEFAULT_PATIENCE_S,\n                        irreversible=irreversible, reload_ok=reload_ok,\n                        expect=expect or None, visual=visual,\n                        insist_strong=ensure and not accept_weak)\n        desc = (f'{ref} {target.get(\"role\")} {target.get(\"name\")!r}' if ref\n                else (f\"{target.get('name')!r} in the row of {near!r}\" if near\n                      else f\"text {text!r}\"))\n        recovery = None\n        if not res.ok and ensure:\n            if irreversible:\n                recovery = self._after_irreversible(tid, target, res)\n            else:\n                fixed, recovery = self._recover(\n                    tid, target, methods=methods,\n                    patience=patience or DEFAULT_PATIENCE_S, expect=expect,\n                    download_dir=download_dir, reload_ok=reload_ok,\n                    visual=visual, first=res)\n                if fixed is not None:\n                    res = fixed\n                elif res.weak is not None:\n                    # Nothing stronger ever came: the look-only answer is all\n                    # there is - returned, and flagged weak (the caller's own\n                    # evidence, e.g. the next step's wait, decides).\n                    recovery[\"accepted_weak\"] = True\n                    res = res.weak\n        self._refs.pop(tid, None)          # the page moved on; refs are stale\n        self._remember(ActionFeedback(page_url, RecordedVerb.ACT,\n                       target=target.get(\"sig\", \"\"), method=res.method,\n                       verified=res.ok, name=target.get(\"name\"),\n                       role=target.get(\"role\"), near=near,\n                       pick=(pick or \"right\") if near else None,\n                       nth=nth if nth != 1 else None,\n                       irreversible=irreversible,\n                       expect_download=bool(expect_download),\n                       expect_new_tab=expect_new_tab,\n                       patience=float(patience) if patience is not None else None))\n        if not res.ok:\n            err = not_verified_error(res, desc)\n            outcomes = [t.get(\"outcome\") for t in res.tried]\n            if irreversible and expect_download and outcomes and all(\n                    o in (\"no-download\", \"error\") for o in outcomes):\n                # A missing local file does not prove the server ignored the\n                # press (D01, 2026-10-01; this replaced S148's next-method\n                # rule), so the hint must not invite another press.\n                err.error.hint = (\n                    f\"Pressed once ({len(outcomes)} dispatch(es)); no download was \"\n                    f\"observed (no new file and no partial file in the folder). \"\n                    f\"That does not prove the press had no effect, so it was not \"\n                    f\"repeated. Observe the page and the browser's downloads \"\n                    f\"before anything else, and ask the user rather than \"\n                    f\"pressing it again.\")\n            elif irreversible and expect_download and \"download-unfinished\" in outcomes:\n                err.error.hint = (\n                    \"A download STARTED (a partial file appeared) but did not \"\n                    \"finish in time. It was not pressed again - check the \"\n                    \"downloads folder before anything else.\")\n            elif irreversible and res.tried:\n                err.error.hint = (\"Sent ONCE and nothing visible changed. It \"\n                                  \"was not repeated because it is marked \"\n                                  \"irreversible - check the page before \"\n                                  \"anything else.\")\n            if recovery:\n                err.error.hint = (err.error.hint or \"\") + \" \" + recovery_summary(recovery)\n                err.error.details = {**(err.error.details or {}),\n                                     \"recovery\": recovery}\n            raise err\n        out = res.to_dict()\n        out.update(tab_id=tid, target=desc)\n        if recovery:\n            out[\"recovery\"] = recovery\n        if learned:\n            out[\"memory_used\"] = learned\n        got = [c.split(\":\", 1)[1] for c in res.changes if c.startswith(\"download:\")]\n        if got and download_dir is not None:\n            out[\"downloaded\"] = [str(download_dir / g) for g in got]\n        ch = set(res.changes)\n        # Same-URL applications (Oracle ADF) change page without a new URL:\n        # the whole tree changes and the pressed control is gone (measured on\n        # the Home link, S138).\n        if ({\"url\", \"title\", \"new-tab\", \"tab-closed\"} & ch\n                or {\"tree\", \"element-gone\"} <= ch):\n            # A new page is a new interface: read it before acting on it.\n            # T6 acted on a page it had not analysed and lost 6.5 minutes.\n            out[\"page_changed\"] = True\n            # A new page gets its own tree read. Same-URL apps (ADF) put the\n            # list and the record under one URL; remembering \"this tab's tree\n            # is dead\" across the change made the readable record page skip\n            # its tree (T8). The site memory's short budget still applies.\n            self._tree_dead.pop(tid, None)\n            out[\"next\"] = (\"the page changed - run `auto rb analyse` before \"\n                           \"acting on it\")\n        return out\n\n    # --- a step that must not fail: recovery ------------------------------------\n\n    def _prepare_from_memory(self, tid: int, url: str | None,\n                             target: dict[str, Any], methods: list[str] | None,\n                             patience: float | None\n                             ) -> tuple[list[str] | None, float | None, list[str]]:\n        \"\"\"Apply, BEFORE the press, what got this control through last time:\n        the second visit should be smooth, not a replay of the whole ladder\n        (measured S145: the covered test button took 2 minutes the first\n        time - the ladder, then the Escape that fixed it).\"\"\"\n        from .act import DEFAULT_METHODS, DEFAULT_PATIENCE_S\n        sig = target.get(\"sig\", \"\")\n        if self.memory is None or not sig:\n            return methods, patience, []\n        worked = self.memory.rank(RankingRequest(url, sig, RankingKind.SUCCESSFUL_TACTICS))\n        applied = []\n        for tactic in worked:\n            if tactic == \"dismiss\":\n                try:\n                    self._escape(tid, target)\n                    applied.append(\"dismiss: Escape pressed before the press\")\n                except ProtocolError:\n                    pass\n            elif tactic == \"patience\":\n                patience = (patience or DEFAULT_PATIENCE_S) * 3\n                applied.append(f\"patience: waiting {patience:.0f} s per try\")\n            elif tactic == \"text\" and target.get(\"name\"):\n                order = list(methods or DEFAULT_METHODS)\n                methods = [\"ocr\"] + [m for m in order if m != \"ocr\"]\n                applied.append(\"text: the drawn text (OCR) is pressed first\")\n        return methods, patience, applied\n\n    def _recover(self, tid: int, target: dict[str, Any], *,\n                 methods: list[str] | None, patience: float,\n                 expect: dict[str, bool], download_dir: Path | None,\n                 reload_ok: bool, visual: bool, first: Any\n                 ) -> tuple[Any, dict[str, Any]]:\n        \"\"\"Try the recovery tactics until the page answers. Returns (the\n        successful Outcome or None, a report of everything tried).\"\"\"\n        from .act import DEFAULT_METHODS, Actor\n        url = self.url_of(tid)\n        sig = target.get(\"sig\", \"\")\n        order = list(RECOVERY_TACTICS)\n        if self.memory is not None and sig:\n            order = list(self.memory.rank(RankingRequest(url, sig, RankingKind.TACTICS,\n                                                        tuple(order))))\n        report: dict[str, Any] = {\"tactics\": [], \"order\": order}\n        research = self._research_in_background(first)\n        port = _RbPort(self, tid, expect, download_dir=download_dir)\n        actor = Actor(port, memory=self.memory)\n        base = list(methods or DEFAULT_METHODS)\n        deadline = time.monotonic() + RECOVERY_BUDGET_S\n        found = None\n        for tactic in order:\n            late = self._answered_late(port, target, first, expect, visual)\n            if late is not None:\n                # The page answered the ladder's press after all: pressing\n                # anything more (an Escape over a dialog that just opened, a\n                # reload) would undo it (S146 audit).\n                report[\"recovered_by\"] = \"late answer (nothing more pressed)\"\n                found = late\n                break\n            if time.monotonic() > deadline and tactic != \"video\":\n                report[\"tactics\"].append({\"tactic\": tactic,\n                                          \"skipped\": \"recovery time budget spent\"})\n                continue\n            try:\n                out = self._tactic(tactic, tid, target, actor, port, base,\n                                   patience, expect, reload_ok, visual, report)\n            except ProtocolError as exc:\n                report[\"tactics\"].append({\"tactic\": tactic, \"ok\": False,\n                                          \"error\": exc.error.message[:160]})\n                self._remember(RecoveryFeedback(url, sig, tactic, False,\n                                                 exc.error.message))\n                continue\n            if out is None:\n                report[\"tactics\"].append({\"tactic\": tactic, \"applicable\": False})\n                continue\n            report[\"tactics\"].append({\"tactic\": tactic, \"ok\": out.ok,\n                                      \"method\": out.method,\n                                      \"changes\": out.changes})\n            self._remember(RecoveryFeedback(url, sig, tactic, out.ok,\n                                             \", \".join(out.changes)))\n            if out.ok:\n                report[\"recovered_by\"] = tactic\n                found = out\n                break\n        report[\"research\"] = self._research_result(research, url, deadline)\n        if found is None:\n            report[\"needs_help\"] = (\n                \"every method and every recovery tactic was tried; the \"\n                \"recording, its analysis and the research are kept - ask the \"\n                \"user (`auto request-help`) with them\")\n        return found, report\n\n    @staticmethod\n    def _answered_late(port: \"_RbPort\", target: dict[str, Any], first: Any,\n                       expect: dict[str, bool], visual: bool) -> Any:\n        \"\"\"A strong change since the page before the ladder's first press,\n        as an Outcome - or None.\"\"\"\n        from .act import Outcome, diff, satisfied, strength\n        origin = getattr(first, \"origin\", None)\n        if not origin:\n            return None\n        try:\n            now = port.snapshot(target, visual=visual)\n        except ProtocolError:\n            return Outcome(True, first.method, [\"tab-closed\"], 0.0, list(first.tried),\n                           EffectState.COMMITTED.value)\n        late = diff(origin, now)\n        if strength(late) == \"strong\" and satisfied(late, expect or None):\n            return Outcome(True, first.method, late, 0.0, list(first.tried),\n                           EffectState.COMMITTED.value)\n        return None\n\n    def _tactic(self, tactic: str, tid: int, target: dict[str, Any], actor: Any,\n                port: \"_RbPort\", base: list[str], patience: float,\n                expect: dict[str, bool], reload_ok: bool, visual: bool,\n                report: dict[str, Any]) -> Any:\n        \"\"\"One recovery tactic; None when it does not apply to this target.\"\"\"\n        from .act import Outcome\n        once = dict(retry_same=False, reload_ok=False, expect=expect or None,\n                    visual=visual, insist_strong=True)\n        if tactic == \"dismiss\":\n            self._escape(tid, target)\n            return actor.act(target, methods=base, patience_s=patience, **once)\n        if tactic == \"patience\":\n            return actor.act(target, methods=base[:2], patience_s=patience * 3,\n                             **once)\n        if tactic == \"text\":\n            name = (target.get(\"name\") or \"\").strip()\n            if not name or target.get(\"role\") == \"text\" or len(name) > 60:\n                return None\n            return actor.act({\"text\": name, \"name\": name, \"role\": \"text\",\n                              \"sig\": target.get(\"sig\", \"\"),\n                              \"nth\": target.get(\"nth\", 1)},\n                             methods=[\"ocr\"], patience_s=patience, **once)\n        if tactic == \"siblings\":\n            if not target.get(\"ref\"):\n                return None\n            self.observe(tid)\n            same = [(r, e) for r, e in (self._refs.get(tid) or {}).items()\n                    if e.get(\"role\") == target.get(\"role\")\n                    and e.get(\"name\") == target.get(\"name\")\n                    and e.get(\"backend\") != target.get(\"backend\")][:3]\n            last = None\n            for r, e in same:\n                last = actor.act({**target, \"ref\": r, \"backend\": e[\"backend\"]},\n                                 methods=[\"cdp\", \"dom\"], patience_s=patience, **once)\n                if last.ok:\n                    return last\n            return last\n        if tactic == \"href\":\n            if (target.get(\"role\") != \"link\" or not target.get(\"backend\")\n                    or expect.get(\"@new-tab\") or expect.get(\"@download\")):\n                return None\n            obs = self.observe(tid)\n            ref = next((r for r, e in (self._refs.get(tid) or {}).items()\n                        if e.get(\"backend\") == target.get(\"backend\")), None)\n            href = (obs.get(\"hrefs\") or {}).get(ref or \"\", \"\")\n            if not href.startswith((\"http://\", \"https://\")):\n                return None\n            before = self.url_of(tid)\n            self.navigate(href, tid)\n            time.sleep(3.0)\n            after = self.url_of(tid)\n            return Outcome(after != before, \"href\", [\"url\"] if after != before else [],\n                           3.0, [{\"method\": \"href\", \"outcome\":\n                                  \"ok\" if after != before else \"no-change\"}])\n        if tactic == \"reload\":\n            if not reload_ok:\n                return None\n            port.reload()\n            time.sleep(6.0)\n            fresh = port.reresolve(target)\n            if not fresh:\n                return Outcome(False, \"\", [\"element-gone-after-reload\"], 0.0, [])\n            target.update(fresh)\n            return actor.act(target, methods=base, patience_s=patience * 2, **once)\n        if tactic == \"video\":\n            at = target.get(\"at\") or self._target_centre(tid, target)\n            box: dict[str, Any] = {}\n\n            def press() -> None:\n                box[\"out\"] = actor.act(target, methods=base[:1],\n                                       patience_s=patience, retry_same=False,\n                                       reload_ok=False, expect=expect or None,\n                                       visual=False, insist_strong=True)\n            rec = self.record_video(tid, during=press, target_at=at,\n                                    title=f\"stuck {target.get('sig', '')}\",\n                                    sig=target.get(\"sig\", \"\"))\n            report[\"video\"] = rec\n            return box.get(\"out\")\n        raise ProtocolError(ErrorCode.UNSUPPORTED, f\"unknown tactic {tactic!r}\")\n\n    def _escape(self, tid: int, target: dict[str, Any]) -> None:\n        \"\"\"Escape, delivered INTO the page: the target is focused first and\n        the key goes to it (and bubbles to the document). A bare key right\n        after a navigation went nowhere - the page had no focus - and the\n        overlay stayed (measured S145: 2 minutes instead of 8 seconds).\"\"\"\n        if target.get(\"backend\"):\n            try:\n                _call(\"focuskey\", {\"tabId\": tid, \"backendNodeId\": target[\"backend\"],\n                                   \"key\": \"escape\"})\n                time.sleep(1.0)\n                return\n            except ProtocolError:\n                pass\n        _call(\"key\", {\"tabId\": tid, \"key\": \"escape\"})\n        time.sleep(1.0)\n\n    def _target_centre(self, tid: int, target: dict[str, Any]) -> list[float] | None:\n        try:\n            snap = _call(\"snapshot\", {\"tabId\": tid,\n                                      \"backendNodeId\": target.get(\"backend\"),\n                                      \"expect\": []}, timeout=30)\n            x, y, w, h = [float(v) for v in str((snap.get(\"elem\") or {})\n                                                .get(\"rect\") or \"\").split(\",\")]\n            return [x + w / 2, y + h / 2]\n        except Exception:\n            return None\n\n    def _after_irreversible(self, tid: int, target: dict[str, Any],\n                            first: Any) -> dict[str, Any]:\n        \"\"\"An irreversible press that showed nothing is never repeated. What\n        can still be done: search, and record what the page does next (a late\n        error message, a slow confirmation) and where.\"\"\"\n        research = self._research_in_background(first)\n        rec = self.record_video(tid, seconds=6.0,\n                                target_at=target.get(\"at\")\n                                or self._target_centre(tid, target),\n                                title=f\"after irreversible {target.get('sig', '')}\",\n                                sig=target.get(\"sig\", \"\"))\n        return {\"tactics\": [], \"not_repeated\": \"irreversible\", \"video\": rec,\n                \"research\": self._research_result(research, self.url_of(tid),\n                                                  time.monotonic() + 30)}\n\n    def _research_in_background(self, first: Any) -> Future[ResearchResult] | None:\n        \"\"\"Submit through the injected port, retaining this operation's context.\"\"\"\n        port = self.research\n        if port is None or not getattr(first, \"stuck\", None):\n            return None\n        request = ResearchRequest(tuple(first.stuck[\"queries\"][:2]))\n        result: Future[ResearchResult] = Future()\n        context = copy_context()\n\n        def run() -> None:\n            if not result.set_running_or_notify_cancel():\n                return\n            try:\n                result.set_result(context.run(port.search, request))\n            except Exception as exc:\n                result.set_exception(exc)\n        th = threading.Thread(target=run, name=\"autoskill-research\", daemon=True)\n        th.start()\n        return result\n\n    def _research_result(self, holder: Future[ResearchResult] | None, url: str | None,\n                         deadline: float) -> dict[str, Any] | None:\n        if holder is None:\n            return None\n        try:\n            res = holder.result(timeout=max(0.0, deadline - time.monotonic()))\n        except FutureTimeout:\n            return {\"error\": \"the search did not finish before the deadline\"}\n        except Exception as exc:\n            return {\"error\": type(exc).__name__}\n        from .contracts.grounding import site_key\n        host = site_key(url)[0]\n        for run in res.runs:\n            self._remember(ResearchFeedback(host, run))\n        top = [{\"source\": r.source, \"title\": r.title[:100], \"url\": r.url}\n               for run in res.runs for r in run.results][:8]\n        return {\"count\": sum(len(run.results) for run in res.runs), \"top\": top,\n                \"refused\": [\"query refused\"] * res.refused_count,\n                \"failed_sources\": sorted({s for run in res.runs for s in run.failed_sources})}\n\n    # --- screen recording --------------------------------------------------------\n\n    def record_video(self, tab_id: int | None, *, seconds: float = 10.0,\n                     during: Any = None, target_at: list[float] | None = None,\n                     title: str = \"\", sig: str = \"\",\n                     with_overlay: bool = False) -> dict[str, Any]:\n        \"\"\"Record the tab's screen - for `seconds`, or while `during()` runs -\n        and analyse it (video.py): video file, contact sheet, where the\n        screen changed, error text that appeared and where. with_overlay\n        keeps the agent's own cursor and status bar in the frames, so the\n        recording can be reviewed as a film of the agent at work.\"\"\"\n        from . import video\n        tid = self.pick_tab(tab_id)\n        self._front(tid)\n        meta: dict[str, Any] = {}\n\n        def grab() -> Any:\n            img, m = self._shot(tid, keep_overlay=with_overlay)\n            meta.update(m)\n            return img\n        rec = video.FrameRecorder(grab).start()\n        try:\n            if during is not None:\n                during()\n            else:\n                time.sleep(max(1.0, min(float(seconds), video.MAX_SECONDS)))\n        finally:\n            frames = rec.stop()\n        analysis = video.analyse(frames, dpr=float(meta.get(\"dpr\") or 1.0),\n                                 target_at=target_at, ocr=self._frame_ocr)\n        stamp = datetime.now().strftime(\"%Y%m%d-%H%M%S\")\n        slug = re.sub(r\"[^A-Za-z0-9]+\", \"-\", title or \"recording\").strip(\"-\")[:40]\n        saved = video.save(frames, self.home / \"videos\" / f\"{stamp}-{slug}\",\n                           analysis, title=title)\n        if rec.errors:\n            saved[\"capture_errors\"] = rec.errors[:3]\n        self._remember(VideoFeedback(self.url_of(tid), sig or title,\n                                     saved.get(\"folder\"), saved.get(\"video\"),\n                                     saved.get(\"contact_sheet\"), saved.get(\"analysis\"),\n                                     saved.get(\"verdict\"), saved.get(\"frames\")))\n        return {\"effect_state\": EffectState.NONE.value, \"tab_id\": tid, **saved,\n                \"changes\": analysis.get(\"changes\"),\n                \"errors\": analysis.get(\"errors\")}\n\n    def _frame_ocr(self, img: Any) -> list[dict[str, Any]]:\n        from . import ocr as _ocr\n        path = self.home / \"scratch\" / f\"frame-{int(time.time() * 1000)}.png\"\n        path.parent.mkdir(parents=True, exist_ok=True)\n        img.save(path)\n        try:\n            return _ocr.recognize(str(path)).get(\"lines\") or []\n        finally:\n            try:\n                path.unlink()\n            except OSError:\n                pass\n\n    def selfreload(self) -> dict[str, Any]:\n        \"\"\"Restart the extension so an updated background script loads.\"\"\"\n        _call(\"selfreload\", timeout=15)\n        return {\"effect_state\": EffectState.COMMITTED.value,\n                \"note\": \"the extension restarts; the bridge reconnects in a \"\n                        \"few seconds - check with `auto rb status`\"}\n\n\nclass _RbPort:\n    \"\"\"The rb surface as the action ladder sees it (act.Port).\"\"\"\n\n    def __init__(self, rb: RbSurface, tid: int, expect: dict[str, bool],\n                 download_dir: Path | None = None) -> None:\n        self.rb = rb\n        self.tid = tid\n        self.expect = expect\n        self.download_dir = download_dir\n\n    def url(self) -> str | None:\n        return self.rb.url_of(self.tid)\n\n    def snapshot(self, target: dict[str, Any], *, visual: bool) -> dict[str, Any]:\n        snap = _call(\"snapshot\", {\"tabId\": self.tid,\n                                  \"backendNodeId\": target.get(\"backend\"),\n                                  \"expect\": [n for n in self.expect\n                                             if not n.startswith(\"@\")]},\n                    timeout=60)\n        if self.download_dir is not None:\n            try:\n                snap[\"downloads\"] = sorted(p.name for p in self.download_dir.iterdir())\n            except OSError:\n                snap[\"downloads\"] = []\n        if visual:\n            try:\n                img, meta = self.rb._shot(self.tid)\n                snap[\"pixels\"] = _crop_around(img, meta, snap.get(\"elem\"),\n                                              target.get(\"at\"))\n            except ProtocolError:\n                raise\n            except Exception:\n                snap[\"pixels\"] = None\n        return snap\n\n    def waiting(self, on: bool) -> None:\n        \"\"\"The waiting dots for an evidence watch: the page is being polled\n        for the press's effect, which is a wait the user should see (S157).\n        Cosmetic - never raises into the ladder.\"\"\"\n        try:\n            _call(\"cue\", {\"tabId\": self.tid, \"wait\": bool(on)})\n        except Exception:\n            pass\n\n    def perform(self, method: str, target: dict[str, Any]) -> dict[str, Any]:\n        if method == \"cdp\":\n            out = _call(\"click\", {\"tabId\": self.tid,\n                                  \"backendNodeId\": target[\"backend\"]})\n            return {\"at\": [round(out.get(\"x\", 0)), round(out.get(\"y\", 0))]}\n        if method == \"dom\":\n            return _call(\"domclick\", {\"tabId\": self.tid,\n                                      \"backendNodeId\": target[\"backend\"]})\n        if method == \"keyboard\":\n            key = (\"space\" if (target.get(\"role\") or \"\") in\n                   (\"checkbox\", \"radio\", \"switch\", \"menuitemcheckbox\")\n                   else \"enter\")\n            return _call(\"focuskey\", {\"tabId\": self.tid,\n                                      \"backendNodeId\": target[\"backend\"],\n                                      \"key\": key})\n        if method == \"position\":\n            x, y = target[\"at\"]\n            out = _call(\"click_at\", {\"tabId\": self.tid, \"x\": x, \"y\": y})\n            return {\"at\": [x, y], \"hit\": out.get(\"hit\")}\n        if method == \"ocr\":\n            found = self.rb.ocr(self.tid, find=target.get(\"text\"),\n                                nth=int(target.get(\"nth\") or 1))\n            hits = [h for h in found.get(\"matches\") or [] if h[\"score\"] >= 0.85]\n            if not hits:\n                raise ProtocolError(ErrorCode.TARGET_NOT_FOUND,\n                                    f\"OCR does not see {target.get('text')!r} \"\n                                    f\"on screen\")\n            x, y = hits[0][\"at\"]\n            target[\"at\"] = [x, y]\n            out = _call(\"click_at\", {\"tabId\": self.tid, \"x\": x, \"y\": y})\n            return {\"at\": [x, y], \"hit\": out.get(\"hit\")}\n        raise ProtocolError(ErrorCode.UNSUPPORTED, f\"unknown method {method!r}\")\n\n    def reload(self) -> None:\n        _call(\"reload\", {\"tabId\": self.tid})\n        self.rb._refs.pop(self.tid, None)\n        time.sleep(4)\n\n    def reresolve(self, target: dict[str, Any]) -> dict[str, Any] | None:\n        \"\"\"The same element on the reloaded page, by role and name.\"\"\"\n        if not target.get(\"backend\"):\n            return dict(target)             # text targets are found afresh\n        deadline = time.monotonic() + 30\n        while time.monotonic() < deadline:\n            try:\n                self.rb.observe(self.tid)\n            except ProtocolError:\n                time.sleep(2)\n                continue\n            for ref, e in (self.rb._refs.get(self.tid) or {}).items():\n                if e.get(\"role\") == target.get(\"role\") and \\\n                        e.get(\"name\") == target.get(\"name\"):\n                    return {**target, \"ref\": ref, \"backend\": e[\"backend\"]}\n            time.sleep(2)\n        return None\n\n\ndef _browser_running() -> dict[str, bool]:\n    \"\"\"Which of the supported browsers has a process now (Windows).\"\"\"\n    import os\n    import subprocess\n    if os.name != \"nt\":\n        return {}\n    try:\n        from .hidden import hidden\n        out = subprocess.run([\"tasklist\", \"/FO\", \"CSV\", \"/NH\"], capture_output=True,\n                             text=True, timeout=10, **hidden()).stdout.lower()\n    except Exception:\n        return {}\n    return {\"Edge\": '\"msedge.exe\"' in out, \"Chrome\": '\"chrome.exe\"' in out}\n\n\ndef _bridge_hint() -> str:\n    \"\"\"Why the bridge cannot be reached, in the user's terms. The bridge\n    host lives inside the browser: with the browser closed there is none\n    (S146 audit: every rb verb failed while Edge was closed, and the hint\n    only said \"Open Chrome\"). Which browser is closed comes first, then the\n    automatic setup route (2026-10-04) that resolves it.\"\"\"\n    try:\n        running = _browser_running()\n    except Exception:\n        running = {}\n    state = \" \".join(f\"{name} is {'running' if up else 'not running'}.\"\n                     for name, up in running.items())\n    if any(running.values()):\n        state += (\" A running browser without a bridge means the AutoSkill \"\n                  \"extension is enabled but not connected, or not enabled.\")\n    return ((state + \" \") if state else \"\") + (\n        \"Run `auto rb ensure --browser <requested-browser>` and complete its \"\n        \"setup state using AutoSkill desktop. Discover, install/enable/reload \"\n        \"the extension automatically; continue only after CONNECTED. Do not \"\n        \"substitute another browser or ask the user to perform routine setup.\")\n\n\ndef recovery_summary(rec: dict[str, Any]) -> str:\n    \"\"\"One line for an error hint: what recovery tried and what it kept.\"\"\"\n    parts = []\n    tried = [t[\"tactic\"] for t in rec.get(\"tactics\") or [] if \"ok\" in t]\n    if tried:\n        parts.append(\"Recovery tried: \" + \", \".join(tried) + \".\")\n    if rec.get(\"not_repeated\"):\n        parts.append(\"Not pressed again (irreversible).\")\n    v = rec.get(\"video\") or {}\n    if v.get(\"verdict\"):\n        parts.append(f\"Screen recording: {v['verdict']} ({v.get('analysis')}).\")\n    r = rec.get(\"research\") or {}\n    if r.get(\"count\"):\n        parts.append(f\"Research kept {r['count']} result(s) in the site memory, \"\n                     f\"e.g. {r['top'][0]['title']!r} ({r['top'][0]['url']}).\")\n    if rec.get(\"needs_help\"):\n        parts.append(\"Ask the user with this evidence (`auto request-help`).\")\n    return \" \".join(parts)\n\n\ndef control_label(c: dict[str, Any]) -> str:\n    \"\"\"A readable name for a control the accessibility tree left unnamed:\n    its title, alt, aria-label or text, else the meaningful tail of its id.\"\"\"\n    for k in (\"title\", \"alt\", \"aria\", \"text\"):\n        if (c.get(k) or \"\").strip():\n            return c[k].strip()\n    ident = (c.get(\"id\") or \"\").replace(\"::icon\", \"\")\n    tail = ident.split(\":\")[-1] if ident else \"\"\n    return f\"{c.get('tag', '?')}#{tail}\" if tail else c.get(\"tag\", \"?\")\n\n\ndef pick_control(controls: list[dict[str, Any]], pick: str,\n                 anchor: list[float] | None = None) -> dict[str, Any] | None:\n    \"\"\"Choose one control of a row: `right` / `left` (the outermost), a\n    1-based number in left-to-right order, or `name:WORD` matched against\n    title, alt, aria-label, text, id and class (case-insensitive). Among\n    several, reachable controls win. Controls of one column (within 12 px of\n    the outermost x) are told apart by `anchor`: the one nearest the text's\n    line wins - measured on an Oracle record, \"View More Details\" (y 740)\n    and \"Expand\" (y 813) share x 1444/1445, and the text was at y 755.\"\"\"\n    if not controls:\n        return None\n    usable = [c for c in controls if c.get(\"reachable\", True)] or controls\n    p = (pick or \"right\").strip().lower()\n    if p in (\"right\", \"left\"):\n        edge = (max if p == \"right\" else min)(c.get(\"cx\", 0) for c in usable)\n        column = [c for c in usable if abs(c.get(\"cx\", 0) - edge) <= 12]\n        if anchor and len(column) > 1:\n            return min(column, key=lambda c: abs(c.get(\"cy\", 0) - anchor[1]))\n        return column[0]\n    if p.isdigit():\n        i = int(p)\n        return controls[i - 1] if 1 <= i <= len(controls) else None\n    if p.startswith(\"name:\"):\n        word = p[5:].strip()\n        for c in usable + [c for c in controls if c not in usable]:\n            hay = \" \".join(str(c.get(k) or \"\") for k in\n                           (\"title\", \"alt\", \"aria\", \"text\", \"id\", \"cls\")).lower()\n            if word and word in hay:\n                return c\n        return None\n    return None\n\n\ndef _crop_around(img: Any, meta: dict[str, Any], elem: dict[str, Any] | None,\n                 at: list[float] | None) -> Any:\n    \"\"\"The part of the screenshot around the target, in device pixels.\"\"\"\n    dpr = float(meta.get(\"dpr\") or 1.0)\n    box = None\n    if elem and elem.get(\"rect\"):\n        try:\n            x, y, w, h = (float(v) for v in str(elem[\"rect\"]).split(\",\"))\n            box = (x, y, w, h)\n        except ValueError:\n            box = None\n    if box is None and at:\n        box = (at[0] - 30, at[1] - 12, 60, 24)\n    if box is None:\n        return img.convert(\"L\")\n    x, y, w, h = box\n    m = VISUAL_MARGIN\n    left = max(0, int((x - m) * dpr))\n    top = max(0, int((y - m) * dpr))\n    right = min(img.size[0], int((x + w + m) * dpr))\n    bottom = min(img.size[1], int((y + h + m) * dpr))\n    if right <= left or bottom <= top:\n        return img.convert(\"L\")\n    return img.crop((left, top, right, bottom)).convert(\"L\")\n");
